INSERT INTO `t_sys_role` VALUES (1,0,'COMPANY','System Access Group','The System Access Group is a structured entity that defines and manages user navigation permissions based on their roles within the system. It ensures that users have access to the appropriate menus, modules, and features relevant to their assigned roles, maintaining security and operational efficiency.','Y','Y','2020-12-26 19:22:51',1,'2025-02-06 20:12:51',1),(2,0,'COMPANY','Business Access Group','The Business Access Group is a structured entity that manages and controls user access within a subscribed company in the reseller system. It defines navigation permissions, role-based access, and feature visibility for company users based on their assigned roles. This ensures a secure, efficient, and customized user experience tailored to the organization\'s operational needs.','Y','Y','2020-12-26 19:22:51',1,'2025-02-06 20:21:46',1);
/*!40000 ALTER TABLE `t_sys_role` ENABLE KEYS */;
UNLOCK TABLES;

